#!/bin/sh
# Build the Orange Pi 5 (RK3588S) direct-boot fixture from pinned packages:
#   OUT/Image.gz            Debian 13 linux-image-arm64 kernel, unmodified (gzip of the Image)
#   OUT/initramfs.cpio.gz   Alpine aarch64 minirootfs + a serial-shell /init
# Usage: scripts/orangepi5-fixture.sh [OUT]   (default cache/orangepi5)
#
# The device tree is generated by the emulator (rk3588::boot), so none is shipped. The kernel
# is the one docs/orangepi5.md was tested with (Debian's generic arm64 flavour: ARCH_ROCKCHIP,
# SERIAL_8250_DW and the GICv3 built in). Downloads are verified against SHA-256; Debian and
# Alpine drop superseded versions, so update the pins together.
set -eu

OUT=${1:-cache/orangepi5}
ALPINE=${ALPINE_MIRROR:-https://dl-cdn.alpinelinux.org/alpine}
DEBIAN=${DEBIAN_MIRROR:-https://deb.debian.org/debian}
ROOTFS=alpine-minirootfs-3.24.4-aarch64.tar.gz
ROOTFS_URL=$ALPINE/v3.24/releases/aarch64/$ROOTFS
ROOTFS_SHA=4b14c18f7e90a063b61462ea1462a5732c154bf6adad594974fe6487cd98a8de
KVER=6.12.107+deb13-arm64
KERNEL_DEB=linux-image-${KVER}-unsigned_6.12.107-1_arm64.deb
KERNEL_URL=$DEBIAN/pool/main/l/linux/$KERNEL_DEB
KERNEL_SHA=2f986ade1a1336423adf2316ea89c3525dd4c05a646b2141626490ca2f388339

mkdir -p "$OUT/downloads"
OUT=$(cd "$OUT" && pwd)   # absolute: the script changes directory below

fetch() { # file url sha256
    if [ ! -f "$OUT/downloads/$1" ]; then
        echo "fetching $2" >&2
        curl -fL --retry 3 -o "$OUT/downloads/$1.part" "$2"
        mv "$OUT/downloads/$1.part" "$OUT/downloads/$1"
    fi
    actual=$(shasum -a 256 "$OUT/downloads/$1" | cut -d' ' -f1)
    if [ "$actual" != "$3" ]; then
        echo "$1: sha256 $actual, expected $3" >&2
        exit 1
    fi
}

fetch "$ROOTFS" "$ROOTFS_URL" "$ROOTFS_SHA"
fetch "$KERNEL_DEB" "$KERNEL_URL" "$KERNEL_SHA"

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# A .deb is an ar archive; the kernel is in data.tar.xz. Debian's arm64 vmlinuz is the
# uncompressed Image (an EFI stub with the arm64 boot header); the site serves it gzipped.
mkdir "$work/deb"
(cd "$work/deb" && ar x "$OUT/downloads/$KERNEL_DEB" data.tar.xz)
tar -xJf "$work/deb/data.tar.xz" -C "$work/deb" "./boot/vmlinuz-$KVER"
cp "$work/deb/boot/vmlinuz-$KVER" "$OUT/Image"
[ "$(dd if="$OUT/Image" bs=1 skip=56 count=4 2>/dev/null)" = ARMd ] || { echo "vmlinuz-$KVER: not an arm64 Image" >&2; exit 1; }
gzip -9n -c "$OUT/Image" > "$OUT/Image.gz"

mkdir "$work/rootfs"
tar -xzf "$OUT/downloads/$ROOTFS" -C "$work/rootfs"
cat > "$work/rootfs/init" <<'INIT'
#!/bin/busybox sh
/bin/busybox mount -t devtmpfs devtmpfs /dev
exec </dev/console >/dev/console 2>&1
/bin/busybox mount -t proc proc /proc
/bin/busybox mount -t sysfs sysfs /sys
/bin/busybox mount -t tmpfs tmpfs /tmp
export HOME=/root PATH=/usr/sbin:/usr/bin:/sbin:/bin PS1='orangepi5# '
echo "RK3588_BOOT_OK: AArch64 Linux BusyBox shell"
# setsid -c makes the console the shell's controlling terminal (job control, ^C).
exec /bin/busybox setsid -c /bin/sh
INIT
chmod 755 "$work/rootfs/init"
(cd "$work/rootfs" && find . | LC_ALL=C sort | cpio -o -H newc -R 0:0 2>/dev/null) |
    gzip -9n > "$OUT/initramfs.cpio.gz"

shasum -a 256 "$OUT/Image.gz" "$OUT/initramfs.cpio.gz"
